import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-128: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short128', durationInSeconds: 35.6, fps: 30, width: 1080, height: 1920 };

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', gap: 24, fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short128: React.FC = () => {
  const frame = useCurrentFrame();
  const CTA = secToFrame(30.6);
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  const lines = [{ text: 'CACHE READS' }, { text: '4X CHEAPER', accent: true }];
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={secToFrame(3.2)}>
        <CoverImage src="projects/short-128/cover.png" out={secToFrame(3.2) - 10} />
        <HookTitle hold onDark kicker="CLAUDE API" lines={lines} />
      </FadeOut>
      <FadeOut at={secToFrame(6.8)}>
        <ToolCard name="Fable 5 cache read" tagline="Per 1M tokens." chip="$1.00" at={secToFrame(3.2) - 2}>
          <Panel>
            <Line k="cache hit" v="$1.00" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(10.6)}>
        <ToolCard name="Fable 5.1 cache read" tagline="Per 1M tokens." chip="$0.25" at={secToFrame(6.8) - 2}>
          <Panel>
            <Line k="cache hit" v="$0.25" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(13.8)}>
        <ToolCard name="Share of input price" tagline="Fable 5.1." chip="2.5%" at={secToFrame(10.6) - 2}>
          <Panel>
            <Line k="0.025 x $10" v="$0.25" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(18.4)}>
        <ToolCard name="Prices unchanged" tagline="Per 1M tokens." chip="SAME" at={secToFrame(13.8) - 2} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="input" v="$10" />
            <Line k="output" v="$50" />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={secToFrame(24.9)}>
        <ToolCard name="Ten 1M-token reads" tagline="Fable 5.1." chip="$2.50" at={secToFrame(18.4) - 2}>
          <Panel>
            <Line k="10 x $0.25" v="$2.50" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Same reads, Fable 5" tagline="Reads only." chip="$10" at={secToFrame(24.9) - 2} chipColor={COLORS.danger}>
          <Panel>
            <Line k="10 x $1.00" v="$10.00" bad />
            <Line k="cache write" v="not incl." />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-128/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="CLAUDE API" lines={lines} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Cache reads, a quarter of the price.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short128;
